import{_ as s,o as t,c as n,a2 as l}from"./chunks/framework.C4u7U0Dw.js";const h=JSON.parse('{"title":"第 12 章 数据与表格：清洗、分析与图表","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md"}'),e={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 12 章 数据与表格：清洗、分析与图表.md"};function o(i,a,r,p,c,d){return t(),n("div",null,[...a[0]||(a[0]=[l(`<h1 id="第-12-章-数据与表格-清洗、分析与图表" tabindex="-1">第 12 章 数据与表格：清洗、分析与图表 <a class="header-anchor" href="#第-12-章-数据与表格-清洗、分析与图表" aria-label="Permalink to &quot;第 12 章 数据与表格：清洗、分析与图表&quot;">​</a></h1><h2 id="_12-1-场景" tabindex="-1">12.1 场景 <a class="header-anchor" href="#_12-1-场景" aria-label="Permalink to &quot;12.1 场景&quot;">​</a></h2><p>数据类任务是我的另一个主场：</p><ul><li><strong>清洗</strong>：去重、补缺、统一格式；</li><li><strong>分析</strong>：汇总、对比、找趋势、找异常；</li><li><strong>产出</strong>：汇总表、图表、报告数据。</li></ul><h2 id="_12-2-数据任务的原则" tabindex="-1">12.2 数据任务的原则 <a class="header-anchor" href="#_12-2-数据任务的原则" aria-label="Permalink to &quot;12.2 数据任务的原则&quot;">​</a></h2><ol><li><strong>先看数据长什么样</strong>：字段、类型、样例行，绝不盲算；</li><li><strong>口径先对齐</strong>：什么是&quot;销售额&quot;？含不含税？按月还是按周？——先问清或先说明假设；</li><li><strong>结果可复核</strong>：给出可复现的脚本/步骤，你能自己再跑一遍；</li><li><strong>不编数</strong>：缺失数据标&quot;缺失&quot;，不脑补。</li></ol><h2 id="_12-3-案例-清洗并汇总一份销售数据" tabindex="-1">12.3 案例：清洗并汇总一份销售数据 <a class="header-anchor" href="#_12-3-案例-清洗并汇总一份销售数据" aria-label="Permalink to &quot;12.3 案例：清洗并汇总一份销售数据&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>data/sales.csv 里有 3 个月的销售记录，帮我：</span></span>
<span class="line"><span>1. 去重（按订单号）、补全缺失的渠道字段（标 Unknown）</span></span>
<span class="line"><span>2. 按渠道+月份汇总销售额和订单量</span></span>
<span class="line"><span>3. 输出汇总表到 output/sales_summary.csv</span></span>
<span class="line"><span>4. 指出趋势和异常（比如某渠道某月暴跌）</span></span></code></pre></div><p><strong>我的做法：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read 前几行（看结构）→ 统计行数/缺失情况 → 写清洗脚本</span></span>
<span class="line"><span>→ 输出中间结果给你抽查 → 汇总 → 写分析要点（带数字依据）</span></span></code></pre></div><h2 id="_12-4-让分析更有说服力" tabindex="-1">12.4 让分析更有说服力 <a class="header-anchor" href="#_12-4-让分析更有说服力" aria-label="Permalink to &quot;12.4 让分析更有说服力&quot;">​</a></h2><p>数据给出后，我还会帮你：</p><ul><li><strong>找异常</strong>：环比/同比变化超过阈值的地方；</li><li><strong>找归因线索</strong>：异常和哪个维度相关（渠道？地区？时间？）；</li><li><strong>给建议</strong>：基于数据的中性建议，不越权替你拍板。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>例：&quot;渠道 B 六月订单量 -32%，是全渠道唯一下降的，</span></span>
<span class="line"><span>    进一步看是华北区贡献了主要降幅，建议核实该区投放或库存情况。&quot;</span></span></code></pre></div><h2 id="_12-5-图表的产出方式" tabindex="-1">12.5 图表的产出方式 <a class="header-anchor" href="#_12-5-图表的产出方式" aria-label="Permalink to &quot;12.5 图表的产出方式&quot;">​</a></h2><ul><li>我可以生成<strong>数据文件 + 绘图脚本</strong>（如 CSV + 脚本）；</li><li>你可以本地运行脚本产出图表，或告诉我输出格式要求；</li><li>图表要配<strong>读图结论</strong>：&quot;这张图说明了什么&quot;比图本身更重要。</li></ul><h2 id="_12-6-数据安全的红线" tabindex="-1">12.6 数据安全的红线 <a class="header-anchor" href="#_12-6-数据安全的红线" aria-label="Permalink to &quot;12.6 数据安全的红线&quot;">​</a></h2><ul><li>敏感数据（客户信息、财务明细）→ 确认你授权我处理；</li><li>结果不外泄：输出文件放在你指定的目录；</li><li>分析口径写进文档：别人拿到你的汇总表，能看懂你是怎么算的。</li></ul><h2 id="_12-7-练习" tabindex="-1">12.7 练习 <a class="header-anchor" href="#_12-7-练习" aria-label="Permalink to &quot;12.7 练习&quot;">​</a></h2><ol><li>给我一个真实数据文件，先做&quot;结构检查&quot;（字段、缺失、样例）；</li><li>让我按你的口径做一个汇总表，并抽查核对；</li><li>让我基于汇总表写出 3 条带数据依据的发现。</li></ol><blockquote><p>小结：数据任务的价值不在&quot;算得快&quot;，而在<strong>口径透明、过程可复核、结论有依据</strong>。</p></blockquote>`,22)])])}const _=s(e,[["render",o]]);export{h as __pageData,_ as default};
